package com.plnt.client.account

import com.plnt.client.core.CoreBridge
import com.plnt.client.model.Bookmark
import java.net.URL
import java.security.MessageDigest
import javax.net.ssl.HttpsURLConnection

/** Intentionally not data classes: autogenerated toString must never expose key/password material. */
class AccountEntry(val bookmark: Bookmark, internal val identity: String, internal val password: String?)
class AccountPreview(val entries: List<AccountEntry>)
class AccountFailure(val userMessage: String, val needsOtp: Boolean = false) : Exception(userMessage)

internal fun accountBookmarkId(account: String, item: String): String = "myts:" +
    MessageDigest.getInstance("SHA-256").digest((account + "\u0000" + item).toByteArray())
        .joinToString("") { "%02x".format(it) }

/** Only these two method/endpoint pairs can be sent. No synchronize/account-write API exists here. */
internal enum class ReadRpc(val path: String, val method: String) {
    LOGIN("authentication", "login"), ITEMS("synchronization", "requestServerItems")
}
internal fun interface AccountTransport { fun call(rpc: ReadRpc, request: ByteArray): ByteArray }

internal class HttpsAccountTransport : AccountTransport {
    override fun call(rpc: ReadRpc, request: ByteArray): ByteArray {
        val method = rpc.method.toByteArray(Charsets.US_ASCII)
        val frame = byteArrayOf(method.size.toByte()) + method + request
        val connection = URL("https://clientapi.myteamspeak.com/${rpc.path}").openConnection() as HttpsURLConnection
        return try {
            connection.requestMethod = "POST"
            connection.instanceFollowRedirects = false
            connection.connectTimeout = 15000
            connection.readTimeout = 20000
            connection.doOutput = true
            connection.useCaches = false
            connection.setRequestProperty("Content-Type", "application/ts3cloud")
            connection.setFixedLengthStreamingMode(frame.size)
            connection.outputStream.use { it.write(frame) }
            if (connection.responseCode != 200) throw AccountFailure("myTeamSpeak returned an HTTP error. Try again later.")
            connection.inputStream.use { input ->
                val out = java.io.ByteArrayOutputStream()
                val buffer = ByteArray(8192)
                while (true) {
                    val count = input.read(buffer)
                    if (count < 0) break
                    if (out.size() + count > 8 * 1024 * 1024) throw AccountFailure("Account response exceeds the test build limit.")
                    out.write(buffer, 0, count)
                }
                buffer.fill(0)
                out.toByteArray()
            }
        } finally { frame.fill(0); connection.disconnect() }
    }
}

class AccountClient internal constructor(
    private val transport: AccountTransport,
    private val validateIdentity: (String) -> Boolean = CoreBridge::importIdentity,
) {
    constructor() : this(HttpsAccountTransport())

    fun fetch(email: String, password: String, otp: String, deviceId: String): AccountPreview {
        try {
            if (email.any { it.code !in 0x21..0x7e }) throw AccountFailure("This test build supports ASCII email addresses only.")
            require(email.isNotBlank() && email.length <= 320 && password.isNotEmpty() && password.length <= 4096)
            require(otp.length <= 32)
            return AccountCrypto.passwords(email, password).use { keys ->
                val request = Proto.Writer().text(1, email).bytes(2, keys.login).number(3, 0)
                    .number(4, 0).number(5, 1).text(7, deviceId).text(9, "Relay for Teamspeak")
                if (otp.isNotBlank()) request.text(6, otp)
                val login = exchange(ReadRpc.LOGIN, request.build())
                try {
                    when (login.number(5).toInt()) {
                        200 -> Unit
                        208 -> throw AccountFailure("Enter the verification code from your authenticator.", true)
                        209 -> throw AccountFailure("That verification code was rejected. Enter a new code.", true)
                        202 -> throw AccountFailure("Email or password was rejected.")
                        211 -> throw AccountFailure("myTeamSpeak requires a device identifier.")
                        212 -> throw AccountFailure("The account recovery key was rejected. Use the official client to recover access.")
                        213 -> throw AccountFailure("No account recovery keys are available. Use the official client to recover access.")
                        else -> throw AccountFailure("myTeamSpeak could not sign in (status ${login.number(5)}).")
                    }
                    val session = login.text(2)
                    val uuid = login.text(4)
                    require(session.isNotBlank() && uuid.isNotBlank())
                    val master = AccountCrypto.unwrap(login.bytes(1), uuid, keys)
                    try { readItems(session, uuid, master) } finally { master.fill(0) }
                } finally { login.clear() }
            }
        } catch (e: AccountFailure) { throw e
        } catch (e: javax.crypto.AEADBadTagException) {
            throw AccountFailure("The account key could not be unlocked. Recovery in the official client may be needed.")
        } catch (e: java.io.IOException) {
            throw AccountFailure("Could not reach myTeamSpeak securely. Check your connection and try again.")
        } catch (e: Exception) {
            // Neither provider exceptions nor upstream bytes may enter diagnostics/UI.
            throw AccountFailure("Account data could not be verified or uses an unsupported format. Nothing was imported.")
        }
    }

    private fun exchange(rpc: ReadRpc, request: ByteArray): Proto {
        val response = try { transport.call(rpc, request) } finally { request.fill(0) }
        return try { Proto(response) } finally { response.fill(0) }
    }

    private fun readItems(session: String, account: String, master: ByteArray): AccountPreview {
        val request = Proto.Writer().text(1, session).number(4, 1)
        for (kind in 0L..1L) request.bytes(2, Proto.Writer().number(1, kind).build())
        val reply = exchange(ReadRpc.ITEMS, request.build())
        val identities = mutableMapOf<String, String>()
        val bookmarks = mutableListOf<Pair<String, Proto>>()
        val seen = mutableSetOf<String>()
        try {
            if (reply.number(1) !in setOf(300L, 301L, 302L)) throw AccountFailure("myTeamSpeak could not read synced items (status ${reply.number(1)}).")
            for (group in reply.messages(2)) try {
                val kind = group.number(1)
                require(kind == 0L || kind == 1L)
                for (detail in group.messages(3)) try {
                    require(seen.size < 2000)
                    if (detail.number(4) != 0L) continue
                    val uuid = detail.text(1)
                    require(uuid.isNotBlank() && uuid.length <= 256 && seen.add(uuid))
                    if (detail.bytes(3).isEmpty()) throw AccountFailure("The service returned item versions without data. This test build cannot import that sync response yet.")
                    val plain = AccountCrypto.decryptItem(master, detail.bytes(3))
                    val item = try { Proto(plain) } finally { plain.fill(0) }
                    try {
                        require(item.text(2) == uuid && item.number(6) == kind)
                        if (kind == 1L) {
                            require(item.has(17) && !item.has(16))
                            val identity = Proto(item.bytes(17))
                            try {
                                val key = identity.text(1)
                                require(key.length in 1..65536 && validateIdentity(key))
                                identities[uuid] = key
                            } finally { identity.clear() }
                        } else {
                            require(item.has(16) && !item.has(17))
                            bookmarks += uuid to Proto(item.bytes(16))
                        }
                    } finally { item.clear() }
                } finally { detail.clear() }
            } finally { group.clear() }
            val entries = bookmarks.map { (uuid, b) ->
                val key = identities[b.text(6)] ?: throw AccountFailure("A synced server references a missing identity. Nothing was imported.")
                val address = b.text(2)
                val port = b.number(3).let { require(it in 0L..65535L); if (it == 0L) 9987 else it.toInt() }
                require(address.isNotBlank() && address.length <= 1024 && port in 1..65535)
                val bookmark = Bookmark(accountBookmarkId(account, uuid), b.text(1).take(256), address, port,
                    b.text(4).ifBlank { "Relay" }.take(256))
                AccountEntry(bookmark, key, b.text(7).ifEmpty { null })
            }
            return AccountPreview(entries)
        } finally {
            reply.clear()
            bookmarks.forEach { it.second.clear() }
            identities.clear()
        }
    }
}
